import React from 'react';

import {
  Random,
  path,
  hash,
  getPoints,
  getColors,
  getAbbr,
  generateVector,
  bezierCommand,
} from '../utils/icon-utils.js';

// This hook is copied from the app-shell repo

export const useFallbackIcon = (name: string, size: number) => {
  const nameHash = hash(name);
  const random = new Random(nameHash);

  const hue = random.next() * 360;
  const saturation = 25 + random.next() * 50;
  const [foregroundColor, backgroundColor] = getColors(hue, saturation);

  const vector = generateVector(4, random);
  const radius = size / 2;
  const points1 = getPoints(vector, size * 0.8, radius, radius);
  const points2 = getPoints(vector, size * 1.6, radius, radius);
  const points3 = getPoints(vector, size * 3.2, radius, radius);

  const text = getAbbr(name);

  return (
    <div style={{ height: size, borderRadius: '3px' }} data-testid="app-icon">
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox={`${-radius} ${-radius} ${size} ${size}`}
      >
        <defs>
          <linearGradient
            id={`gradient_${nameHash}`}
            x1="0"
            y1="0"
            x2="1"
            y2="1"
          >
            <stop offset="0%" stopColor={foregroundColor} />
            <stop offset="75%" stopColor={backgroundColor} />
          </linearGradient>
        </defs>

        <rect
          width={size}
          height={size}
          fill={backgroundColor}
          x={-size / 2}
          y={-size / 2}
        />

        <path
          d={path(points1, bezierCommand)}
          fill={`url(#gradient_${nameHash})`}
          opacity="0.8"
        />
        <path
          d={path(points2, bezierCommand)}
          fill={`url(#gradient_${nameHash})`}
          opacity="0.6"
        />
        <path
          d={path(points3, bezierCommand)}
          fill={`url(#gradient_${nameHash})`}
          opacity="0.4"
        />

        <text
          fill="white"
          fontFamily="Roboto,Helvetica,sans-serif"
          fontSize={size / 3}
          x={-(size / 2) + size / 8}
          y={size / 3}
        >
          {text}
        </text>
      </svg>
    </div>
  );
};
